+#ifdef __APPLE__
+	return SDL_WINDOW_FULLSCREEN_DESKTOP;
+#else
+	return borderless ? SDL_WINDOW_FULLSCREEN_DESKTOP : SDL_WINDOW_FULLSCREEN;
+#endif
